def union_shortest(k):
    inp,out=G[f'Demo pair {k} input'],G[f'Demo pair {k} output']
    H,W=len(inp),len(inp[0])
    colored={(i,j) for i in range(H) for j in range(W) if inp[i][j]==0 and out[i][j]==2}
    seed=[(i,j) for i in range(H) for j in range(W) if inp[i][j]==2][0]
    bandrows={r for r in range(H) if any(inp[r][c]==8 for c in range(W))}
    hubs=set()
    for r in bandrows:
        for c in range(W):
            if inp[r][c]==0:
                L=R=None
                for cc in range(c,-1,-1):
                    if inp[r][cc]==8: L=c-cc; break
                for cc in range(c+1,W):
                    if inp[r][cc]==8: R=cc-c; break
                if L is not None and R is not None and min(L,R)<=2:
                    hubs.add((r,c))
    hubs|={seed}
    pts=list(hubs)
    allz={(r,c) for r in range(H) for c in range(W) if inp[r][c]==0}
    pred=set()
    for a,b in itertools.combinations(pts,2):
        dist={a:0}; par={a:None}; q=deque([a]); reached=False
        while q:
            cur=q.popleft()
            if cur==b: reached=True; break
            r,c=cur
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and (nr,nc) in allz and (nr,nc) not in dist:
                    dist[(nr,nc)]=dist[cur]+1; par[(nr,nc)]=cur; q.append((nr,nc))
        if not reached or b not in dist: continue
        cur=b
        while cur is not None and cur!=a:
            pred.add(cur); cur=par[cur]
    miss=sum(1 for p in colored if p not in pred); extr=sum(1 for p in pred if p not in colored)
    print('demo',k,'miss',miss,'extr',extr,'n_hubs',len(hubs))
    return miss,extr,pred,hubs,colored
